# ==============================================================================
# scripts/97_fill_31dm_sawlog_price_gap.R
#
# Purpose : Fill the known 31 dm sawlog price gap in the default_2021 price
#           matrices by interpolating from the existing stepwise-increasing
#           values, so 31 dm sawlog candidates (already generated by the
#           optimizer per LengthClasses_spruce_pine_default.csv) can be
#           priced and selected.
#
# Formula : Price(31dm) = 2 x Price(34dm) - Price(37dm)
#                       = Price(34dm) - (Price(37dm) - Price(34dm))
#           i.e. extrapolate the row's 34->37dm step one step backward.
#           Verified (2026-08-03) across both species: Price(37dm) is always
#           >= Price(34dm) for every PriceDiameterClass_cm (diff 0-14
#           NOK/m3, never negative), so this always yields
#           Price(31dm) <= Price(34dm), preserving the increasing trend, and
#           is exact-integer (no rounding needed).
#
# Provenance : New rows are marked PriceSource = "Interpolated",
#           PriceSourceFile = NA, and a Notes string documenting the
#           formula, so they remain traceable and are never mistaken for
#           values sourced from PriceMatrixGran.xlsx / PriceMatrixFuru.xlsx.
#
# Files modified (all three, kept in sync):
#   inputs/price_matrices/PriceMatrix_spruce_sawlog_default_2021.csv
#   inputs/price_matrices/PriceMatrix_pine_sawlog_default_2021.csv
#   inputs/price_matrices/PriceMatrix_long_default_2021.csv   (canonical file
#     actually loaded by the app via load_price_matrix_long())
#
# ==============================================================================

suppressPackageStartupMessages(library(readr))

root_dir <- "S:/Prosjekter/52106_SFI_SmartForest/optBuck/nfiBuck"
pm_dir   <- file.path(root_dir, "inputs", "price_matrices")

INTERP_NOTE <- "Interpolated: 2x34dm - 37dm (extrapolated stepwise trend); not in original source spreadsheet"

#' Build 31 dm rows for one sawlog product by extrapolating from 34/37 dm.
make_31dm_rows <- function(df) {
  d34 <- df[df$LengthClass_dm == 34L, ]
  d37 <- df[df$LengthClass_dm == 37L, ]

  m <- merge(
    d34, d37[, c("PriceDiameterClass_cm", "PriceNOKperM3")],
    by = "PriceDiameterClass_cm", suffixes = c("", "_37"))

  price_31 <- 2L * m$PriceNOKperM3 - m$PriceNOKperM3_37

  stopifnot(
    "31dm price must be positive"        = all(price_31 > 0),
    "31dm price must not exceed 34dm"    = all(price_31 <= m$PriceNOKperM3)
  )

  new_rows <- m[, setdiff(names(m), c("PriceNOKperM3_37"))]
  new_rows$LengthClass_dm  <- 31L
  new_rows$LengthClass_cm  <- 310L
  new_rows$PriceNOKperM3   <- price_31
  new_rows$PriceSource     <- "Interpolated"
  new_rows$PriceSourceFile <- NA_character_
  new_rows$Notes           <- INTERP_NOTE

  new_rows[, names(df)]
}

#' Append 31 dm rows to a per-species (or long) sawlog matrix, in place order.
add_31dm_to_matrix <- function(df, product_keys) {
  pieces <- lapply(product_keys, function(pk) {
    sub <- df[df$ProductKey == pk & !is.na(df$LengthClass_dm), ]
    if (nrow(sub) == 0L) return(NULL)
    make_31dm_rows(sub)
  })
  new_rows <- do.call(rbind, pieces[!vapply(pieces, is.null, logical(1))])

  out <- rbind(df, new_rows)
  out <- out[order(out$ProductKey, out$PriceDiameterClass_cm, out$LengthClass_dm), ]
  rownames(out) <- NULL
  out
}


# ---- spruce sawlog matrix ----------------------------------------------------

sp_path <- file.path(pm_dir, "PriceMatrix_spruce_sawlog_default_2021.csv")
sp <- as.data.frame(read_csv(sp_path, show_col_types = FALSE))
n_sp_before <- nrow(sp)
sp <- add_31dm_to_matrix(sp, "spruce_sawlog")
n_sp_added <- nrow(sp) - n_sp_before
cat(sprintf("spruce sawlog matrix: %d rows -> %d rows (+%d)\n",
            n_sp_before, nrow(sp), n_sp_added))
write_csv(sp, sp_path)


# ---- pine sawlog matrix -------------------------------------------------------

pi_path <- file.path(pm_dir, "PriceMatrix_pine_sawlog_default_2021.csv")
pi <- as.data.frame(read_csv(pi_path, show_col_types = FALSE))
n_pi_before <- nrow(pi)
pi <- add_31dm_to_matrix(pi, "pine_sawlog")
n_pi_added <- nrow(pi) - n_pi_before
cat(sprintf("pine sawlog matrix: %d rows -> %d rows (+%d)\n",
            n_pi_before, nrow(pi), n_pi_added))
write_csv(pi, pi_path)


# ---- canonical long matrix (actually loaded by the app) ----------------------

long_path <- file.path(pm_dir, "PriceMatrix_long_default_2021.csv")
long <- as.data.frame(read_csv(long_path, show_col_types = FALSE))
n_long_before <- nrow(long)
long <- add_31dm_to_matrix(long, c("spruce_sawlog", "pine_sawlog"))
n_long_added <- nrow(long) - n_long_before
cat(sprintf("long price matrix: %d rows -> %d rows (+%d)\n",
            n_long_before, nrow(long), n_long_added))
write_csv(long, long_path)


# ---- summary -------------------------------------------------------------

stopifnot(
  "expected 39 new rows for spruce" = n_sp_added == 39L,
  "expected 39 new rows for pine"   = n_pi_added == 39L,
  "expected 78 new rows in long matrix" = n_long_added == 78L
)

cat("\nDone. 31 dm sawlog price gap filled via interpolation.\n")
cat(sprintf("  spruce_sawlog: +%d rows\n  pine_sawlog:   +%d rows\n  long matrix:   +%d rows\n",
            n_sp_added, n_pi_added, n_long_added))
